import { NextRequest } from "next/server";
import fs from "fs";
import path from "path";

const DATA_DIR  = path.join(process.cwd(), "data");
const DATA_FILE = path.join(DATA_DIR, "waitlist.json");

function ensureDataFile() {
  if (!fs.existsSync(DATA_DIR))  fs.mkdirSync(DATA_DIR, { recursive: true });
  if (!fs.existsSync(DATA_FILE)) fs.writeFileSync(DATA_FILE, "[]", "utf-8");
}

function readEmails(): string[] {
  try {
    return JSON.parse(fs.readFileSync(DATA_FILE, "utf-8"));
  } catch {
    return [];
  }
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const email: unknown = body?.email;

    /* ── Validate ── */
    if (!email || typeof email !== "string") {
      return Response.json({ error: "Email is required." }, { status: 400 });
    }

    const normalized = email.trim().toLowerCase();
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!emailRegex.test(normalized)) {
      return Response.json({ error: "Invalid email address." }, { status: 400 });
    }

    /* ── Persist (dev: local JSON file | prod: replace with Supabase in Phase 3) ── */
    ensureDataFile();
    const existing = readEmails();

    if (existing.includes(normalized)) {
      return Response.json(
        { error: "You're already on the list! We'll see you on drop day." },
        { status: 409 }
      );
    }

    existing.push(normalized);
    fs.writeFileSync(DATA_FILE, JSON.stringify(existing, null, 2), "utf-8");

    console.log(`[Knytra Waitlist] ✅ New signup: ${normalized} (total: ${existing.length})`);

    return Response.json(
      { success: true, message: "You're on the list. We'll hit you up on launch day." },
      { status: 200 }
    );
  } catch (err) {
    console.error("[Knytra Waitlist] Error:", err);
    return Response.json({ error: "Internal server error." }, { status: 500 });
  }
}
